-- Wat is nieuw: werkbalk van de calculatie op één regel (live op 16-10-2026).
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-16','verbeterd','Calculatie','Werkbalk van de calculatie op één regel',
   'De knoppen boven de calculatie staan nu op één regel, ook op een laptop, zodat er meer regels in beeld passen. Terug naar de versies zit vooraan in de balk, Behandeling per code en Uren vind je onder Bewerken, en rechts staan Uitvraag, Controle en Offerte op volgorde. Het paneel Uitvraag en het paneel Controle staan niet meer tegelijk open; het ene sluit als je het andere opent.');
